161|/**
162| * xmlFuzzWriteInt:
163| * @out:  output file
164| * @v:  integer to write
165| * @size:  size of integer in bytes
166| *
167| * Write an integer to the fuzz data.
168| */
169|void
170|xmlFuzzWriteInt(FILE *out, size_t v, int size) {
171|    int shift;
172|
173|    while (size > (int) sizeof(size_t)) {
174|        putc(0, out);
175|        size--;
176|    }
177|
178|    shift = size * 8;
179|    while (shift > 0) {
180|        shift -= 8;
181|        putc((v >> shift) & 255, out);
182|    }
183|}
