191|size_t
192|xmlFuzzReadInt(int size) {
193|    size_t ret = 0;
194|
195|    while ((size > 0) && (fuzzData.remaining > 0)) {
196|        unsigned char c = (unsigned char) *fuzzData.ptr++;
197|        fuzzData.remaining--;
198|        ret = (ret << 8) | c;
199|        size--;
200|    }
201|
202|    return ret;
203|}
