2245|xmlXIncludeDoProcess(xmlXIncludeCtxtPtr ctxt, xmlNodePtr tree) {
2246|    xmlXIncludeRefPtr ref;
2247|    xmlNodePtr cur;
2248|    int ret = 0;
2249|    int i, start;
2250|
2251|    /*
2252|     * First phase: lookup the elements in the document
2253|     */
2254|    start = ctxt->incNr;
2255|    cur = tree;
2256|    do {
2257|	/* TODO: need to work on entities -> stack */
2258|        if (xmlXIncludeTestNode(ctxt, cur) == 1) {
2259|            ref = xmlXIncludeExpandNode(ctxt, cur);
2260|            /*
2261|             * Mark direct includes.
2262|             */
2263|            if (ref != NULL)
2264|                ref->replace = 1;
2265|        } else if ((cur->children != NULL) &&
2266|                   ((cur->type == XML_DOCUMENT_NODE) ||
2267|                    (cur->type == XML_ELEMENT_NODE))) {
2268|            cur = cur->children;
2269|            continue;
2270|        }
2271|        do {
2272|            if (cur == tree)
2273|                break;
2274|            if (cur->next != NULL) {
2275|                cur = cur->next;
2276|                break;
2277|            }
2278|            cur = cur->parent;
2279|        } while (cur != NULL);
2280|    } while ((cur != NULL) && (cur != tree));
2281|
2282|    /*
2283|     * Second phase: extend the original document infoset.
2284|     */
2285|    for (i = start; i < ctxt->incNr; i++) {
2286|	if (ctxt->incTab[i]->replace != 0) {
2287|            if ((ctxt->incTab[i]->inc != NULL) ||
2288|                (ctxt->incTab[i]->emptyFb != 0)) {	/* (empty fallback) */
2289|                xmlXIncludeIncludeNode(ctxt, ctxt->incTab[i]);
2290|            }
2291|            ctxt->incTab[i]->replace = 0;
2292|        } else {
2293|            /*
2294|             * Ignore includes which were added indirectly, for example
2295|             * inside xi:fallback elements.
2296|             */
2297|            if (ctxt->incTab[i]->inc != NULL) {
2298|                xmlFreeNodeList(ctxt->incTab[i]->inc);
2299|                ctxt->incTab[i]->inc = NULL;
2300|            }
2301|        }
2302|	ret++;
2303|    }
2304|
2305|    if (ctxt->isStream) {
2306|        /*
2307|         * incTab references nodes which will eventually be deleted in
2308|         * streaming mode. The table is only required for XPointer
2309|         * expressions which aren't allowed in streaming mode.
2310|         */
2311|        for (i = 0;i < ctxt->incNr;i++) {
2312|            xmlXIncludeFreeRef(ctxt->incTab[i]);
2313|        }
2314|        ctxt->incNr = 0;
2315|    }
2316|
2317|    return(ret);
