1909|static xmlXIncludeRefPtr
1910|xmlXIncludeExpandNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node) {
1911|    xmlXIncludeRefPtr ref;
1912|    int i;
1913|
1914|    if (ctxt->fatalErr)
1915|        return(NULL);
1916|    if (ctxt->depth >= XINCLUDE_MAX_DEPTH) {
1917|        xmlXIncludeErr(ctxt, node, XML_XINCLUDE_RECURSION,
1918|                       "maximum recursion depth exceeded\n", NULL);
1919|        ctxt->fatalErr = 1;
1920|        return(NULL);
1921|    }
1922|
1923|#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
1924|    /*
1925|     * The XInclude engine offers no protection against exponential
1926|     * expansion attacks similar to "billion laughs". Avoid timeouts by
1927|     * limiting the total number of replacements when fuzzing.
1928|     *
1929|     * Unfortuately, a single XInclude can already result in quadratic
1930|     * behavior:
1931|     *
1932|     *     <doc xmlns:xi="http://www.w3.org/2001/XInclude">
1933|     *       <xi:include xpointer="xpointer(//e)"/>
1934|     *       <e>
1935|     *         <e>
1936|     *           <e>
1937|     *             <!-- more nested elements -->
1938|     *           </e>
1939|     *         </e>
1940|     *       </e>
1941|     *     </doc>
1942|     */
1943|    if (ctxt->incTotal >= 20)
1944|        return(NULL);
1945|    ctxt->incTotal++;
1946|#endif
1947|
1948|    for (i = 0; i < ctxt->incNr; i++) {
1949|        if (ctxt->incTab[i]->elem == node) {
1950|            if (ctxt->incTab[i]->expanding) {
1951|                xmlXIncludeErr(ctxt, node, XML_XINCLUDE_RECURSION,
1952|                               "inclusion loop detected\n", NULL);
1953|                return(NULL);
1954|            }
1955|            return(ctxt->incTab[i]);
1956|        }
1957|    }
1958|
1959|    ref = xmlXIncludeAddNode(ctxt, node);
1960|    if (ref == NULL)
1961|        return(NULL);
1962|    ref->expanding = 1;
1963|    ctxt->depth++;
1964|    xmlXIncludeLoadNode(ctxt, ref);
1965|    ctxt->depth--;
1966|    ref->expanding = 0;
1967|
1968|    return(ref);
1969|}

