2176|        (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS))) {
2177|	if (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS)) {
2178|	    if (ctxt->legacy == 0) {
2179|#if 0 /* wait for the XML Core Working Group to get something stable ! */
