2181|	               "Deprecated XInclude namespace found, use %s",
2182|		                XINCLUDE_NS);
2183|#endif
2184|	        ctxt->legacy = 1;
2185|	    }
2186|	}
2187|	if (xmlStrEqual(node->name, XINCLUDE_NODE)) {
2188|	    xmlNodePtr child = node->children;
2189|	    int nb_fallback = 0;
2190|
2191|	    while (child != NULL) {
2192|		if ((child->type == XML_ELEMENT_NODE) &&
2193|		    (child->ns != NULL) &&
2194|		    ((xmlStrEqual(child->ns->href, XINCLUDE_NS)) ||
2195|		     (xmlStrEqual(child->ns->href, XINCLUDE_OLD_NS)))) {
