2202|		    }
2203|		    if (xmlStrEqual(child->name, XINCLUDE_FALLBACK)) {
2204|			nb_fallback++;
2205|		    }
2206|		}
2207|		child = child->next;
2208|	    }
2209|	    if (nb_fallback > 1) {
2210|		xmlXIncludeErr(ctxt, node, XML_XINCLUDE_FALLBACKS_IN_INCLUDE,
2211|			       "%s has multiple fallback children\n",
2212|		               XINCLUDE_NODE);
2213|		return(0);
2214|	    }
2215|	    return(1);
2216|	}
2217|	if (xmlStrEqual(node->name, XINCLUDE_FALLBACK)) {
2218|	    if ((node->parent == NULL) ||
2219|		(node->parent->type != XML_ELEMENT_NODE) ||
2220|		(node->parent->ns == NULL) ||
2221|		((!xmlStrEqual(node->parent->ns->href, XINCLUDE_NS)) &&
2222|		 (!xmlStrEqual(node->parent->ns->href, XINCLUDE_OLD_NS))) ||
