611|/**
612| * xmlVRaiseError:
613| * @schannel: the structured callback channel
614| * @channel: the old callback channel
615| * @data: the callback data
616| * @ctx: the parser context or NULL
617| * @ctx: the parser context or NULL
618| * @domain: the domain for the error
619| * @code: the code for the error
620| * @level: the xmlErrorLevel for the error
621| * @file: the file source of the error (or NULL)
622| * @line: the line of the error or 0 if N/A
623| * @str1: extra string info
624| * @str2: extra string info
625| * @str3: extra string info
626| * @int1: extra int info
627| * @col: column number of the error or 0 if N/A
628| * @msg:  the message to display/transmit
629| * @ap:  extra parameters for the message display
630| *
631| * Update the appropriate global or contextual error structure,
632| * then forward the error message down the parser or generic
633| * error callback handler
634| *
635| * Returns 0 on success, -1 if a memory allocation failed.
636| */
637|int
638|xmlVRaiseError(xmlStructuredErrorFunc schannel,
639|               xmlGenericErrorFunc channel, void *data, void *ctx,
640|               xmlNode *node, int domain, int code, xmlErrorLevel level,
641|               const char *file, int line, const char *str1,
642|               const char *str2, const char *str3, int int1, int col,
643|               const char *msg, va_list ap)
644|{
645|    xmlParserCtxtPtr ctxt = NULL;
646|    /* xmlLastError is a macro retrieving the per-thread global. */
647|    xmlErrorPtr lastError = &xmlLastError;
648|    xmlErrorPtr to = lastError;
649|
650|    if (code == XML_ERR_OK)
651|        return(0);
652|    if ((xmlGetWarningsDefaultValue == 0) && (level == XML_ERR_WARNING))
653|        return(0);
654|
655|    if ((domain == XML_FROM_PARSER) || (domain == XML_FROM_HTML) ||
656|        (domain == XML_FROM_DTD) || (domain == XML_FROM_NAMESPACE) ||
657|	(domain == XML_FROM_IO) || (domain == XML_FROM_VALID)) {
658|	ctxt = (xmlParserCtxtPtr) ctx;
659|
660|        if (ctxt != NULL)
661|            to = &ctxt->lastError;
662|    }
663|
664|    if (xmlVUpdateError(to, ctxt, node, domain, code, level, file, line,
665|                        str1, str2, str3, int1, col, msg, ap))
666|        return(-1);
667|
668|    if (to != lastError) {
669|        if (xmlCopyError(to, lastError) < 0)
670|            return(-1);
671|    }
672|
673|    if (schannel != NULL) {
674|	schannel(data, to);
675|    } else if (xmlStructuredError != NULL) {
676|        xmlStructuredError(xmlStructuredErrorContext, to);
677|    } else if ((ctxt == NULL) && (channel == NULL)) {
678|	xmlGenericError(xmlGenericErrorContext, "%s", to->message);
679|    } else if (channel != NULL) {
680|	channel(data, "%s", to->message);
681|    }
682|
683|    return(0);
684|}
