845|/**
846| * xmlResetError:
847| * @err: pointer to the error.
848| *
849| * Cleanup the error.
850| */
851|void
852|xmlResetError(xmlErrorPtr err)
853|{
854|    if (err == NULL)
855|        return;
856|    if (err->code == XML_ERR_OK)
857|        return;
858|    if (err->message != NULL)
859|        xmlFree(err->message);
