663|void
664|xmlXPathErr(xmlXPathParserContextPtr ctxt, int code)
665|{
666|    xmlStructuredErrorFunc serror = NULL;
667|    void *data = NULL;
668|    xmlNodePtr node = NULL;
669|    int res;
670|
671|    if (ctxt == NULL)
672|        return;
673|    if ((code < 0) || (code > MAXERRNO))
674|	code = MAXERRNO;
675|    /* Only report the first error */
676|    if (ctxt->error != 0)
677|        return;
678|
679|    ctxt->error = code;
680|
681|    if (ctxt->context != NULL) {
682|        xmlErrorPtr err = &ctxt->context->lastError;
683|
684|        /* Don't overwrite memory error. */
685|        if (err->code == XML_ERR_NO_MEMORY)
686|            return;
687|
688|        /* cleanup current last error */
689|        xmlResetError(err);
690|
691|        err->domain = XML_FROM_XPATH;
692|        err->code = code + XML_XPATH_EXPRESSION_OK - XPATH_EXPRESSION_OK;
693|        err->level = XML_ERR_ERROR;
694|        if (ctxt->base != NULL) {
695|            err->str1 = (char *) xmlStrdup(ctxt->base);
696|            if (err->str1 == NULL) {
697|                xmlXPathPErrMemory(ctxt);
698|                return;
699|            }
700|        }
701|        err->int1 = ctxt->cur - ctxt->base;
702|        err->node = ctxt->context->debugNode;
703|
704|        serror = ctxt->context->error;
705|        data = ctxt->context->userData;
706|        node = ctxt->context->debugNode;
707|    }
708|
709|    res = __xmlRaiseError(serror, NULL, data, NULL, node, XML_FROM_XPATH,
710|                          code + XML_XPATH_EXPRESSION_OK - XPATH_EXPRESSION_OK,
711|                          XML_ERR_ERROR, NULL, 0,
712|                          (const char *) ctxt->base, NULL, NULL,
713|                          ctxt->cur - ctxt->base, 0,
714|                          "%s", xmlXPathErrorMessages[code]);
715|    if (res < 0)
716|        xmlXPathPErrMemory(ctxt);
717|}

